// ---- URL ROUTER --------------------------------------------------------
// Lightweight stage ↔ URL mapping, no library. Top-level pages get clean
// URLs (/help, /knowledge, /onboarding, etc.); transient sub-states
// (/help → questions → search-results) all live under the parent path so
// users can still bookmark / share / refresh and land in the right place.
// In production the IT Hub is mounted under /portal/ on slicedesk's
// nginx, so every URL we push to the browser needs that prefix or
// we'd accidentally bounce users out to slicedesk's catch-all. The
// base is read once at load time from the server-rendered <base> tag
// or window.IT_HUB_BASE, with a sensible /portal default. Set
// window.IT_HUB_BASE='' for local dev without a prefix.
const APP_BASE = (() => {
  if (typeof window !== "undefined") {
    if (window.IT_HUB_BASE !== undefined) return String(window.IT_HUB_BASE).replace(/\/$/, "");
    // Detect from <base href="..."> emitted by Vite when base != "/"
    const baseEl = document.querySelector("base[href]");
    if (baseEl) {
      const u = baseEl.getAttribute("href") || "/";
      const trimmed = u.replace(/\/$/, "");
      if (trimmed) return trimmed;
    }
  }
  // Same source main.jsx uses for the /api prefix: Vite's base ('/portal/' in
  // prod, '/' when the dev server runs with VITE_BASE_PATH=/).
  const viteBase = import.meta.env?.BASE_URL;
  if (viteBase !== undefined) return String(viteBase).replace(/\/$/, "");
  return "/portal";
})();
const withBase = (p) => APP_BASE + p;

// Module mode: SliceDesk embeds us cross-origin in an iframe. There we must
// never rewrite the iframe's path — the URL carries ?hub_token=… which every
// API call reads live (main.jsx), and pushState would both wipe it and stack
// history entries that hijack the parent page's back button. Deep links and
// shareable URLs go through the parent shell (slicedesk:module-query
// postMessage) instead.
const IS_EMBEDDED = (() => {
  if (typeof window === "undefined") return false;
  try { return window.self !== window.top; } catch { return true; }
})();

const STAGE_TO_PATH = {
  landing: "/",
  questions: "/help",
  "search-results": "/help",
  ask: "/help",
  knowledge: "/knowledge",
  status: "/status",
  tickets: "/tickets",
  request: "/request",
  notifications: "/notifications",
};
const PATH_TO_STAGE = {
  "/": "landing",
  "/help": "landing",
  "/knowledge": "knowledge",
  "/status": "status",
  "/tickets": "tickets",
  "/request": "request",
  "/notifications": "notifications",
};
function stageFromPath(path) {
  // Strip the deploy base path first so /portal/knowledge → /knowledge,
  // then keep only the first path segment so /knowledge/foo still
  // resolves to knowledge. Falls back to landing for unknown paths
  // (including the retired /onboarding and /offboarding links).
  let p = path || "/";
  if (APP_BASE && p.startsWith(APP_BASE)) p = p.slice(APP_BASE.length) || "/";
  const seg = "/" + ((p || "/").split("/").filter(Boolean)[0] || "");
  return PATH_TO_STAGE[seg] || "landing";
}

// ---------- APP ROOT ----------
function App() {
  const [tweaks, setTweaksState] = useTweaks(TWEAK_DEFAULTS);
  // Initial stage comes from the URL — supports deep links and refreshes.
  // Embedded, the iframe's own pathname is always just the mount point (the
  // parent never rewrites it — see IS_EMBEDDED below), so the real deep-link
  // signal is the `path` query param the parent's ModulePage forwards from
  // its own ?path=; standalone, it's the actual pathname as usual.
  const [stage, setStageRaw] = useState(() => {
    if (typeof window === "undefined") return "landing";
    if (IS_EMBEDDED) {
      let p = null;
      try { p = new URLSearchParams(window.location.search).get("path"); } catch {}
      return p ? stageFromPath(p) : "landing";
    }
    return stageFromPath(window.location.pathname);
  });
  // Wrap setStage so the address bar stays in sync. We only push when the
  // mapped path actually changes — transient sub-stages (questions, search-
  // results) share their parent's path, so they don't
  // pollute browser history.
  const setStage = React.useCallback((next) => {
    setStageRaw((prev) => {
      const prevPath = STAGE_TO_PATH[prev] || "/";
      const nextPath = STAGE_TO_PATH[next] || "/";
      if (prevPath !== nextPath && typeof window !== "undefined") {
        if (IS_EMBEDDED) {
          // Embedded: leave the iframe URL alone (see IS_EMBEDDED) — tell the
          // parent shell instead, the same way the guide/item deep-links do,
          // so /modules/167 picks up ?path=/request instead of sitting on
          // the generic module URL until a catalog item happens to be opened.
          try { window.parent.postMessage({ type: "slicedesk:module-query", params: { path: nextPath } }, "*"); } catch {}
        } else {
          // Standalone: carry the query string across — dropping it used to
          // strip params like ?guide / ?ticket mid-navigation; the effects
          // that own each param add/remove theirs via replaceState.
          try { window.history.pushState({ stage: next }, "", withBase(nextPath) + window.location.search); } catch {}
        }
      }
      return next;
    });
  }, []);
  // Sync stage when the user uses the browser back/forward buttons.
  React.useEffect(() => {
    const onPop = () => {
      setStageRaw(stageFromPath(window.location.pathname));
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const [query, setQuery] = useState("");
  const [outcome, setOutcome] = useState(null);
  const [guide, setGuide] = useState(null);

  // Deep-link: open `/portal/?guide=N` directly into the guide view.
  // Done as a one-shot effect on mount; the URL query param doesn't drive
  // ongoing state because the user can always close to /portal/.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const id = params.get("guide");
    if (!id) return;
    fetch(`/api/guides/${encodeURIComponent(id)}`, { credentials: 'include' })
      .then((r) => (r.ok ? r.json() : null))
      .then((g) => {
        if (g && g.id) setGuide({ id: g.id, title: g.title, category: g.category });
      })
      .catch(() => {});
  }, []);

  // Keep ?guide=N in the URL while a guide is open (and mirror it to the
  // parent SliceDesk shell via postMessage when embedded) so users can just
  // copy the address bar to share an article — no Share button required.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const url = new URL(window.location.href);
      if (guide && guide.id) url.searchParams.set("guide", String(guide.id));
      else url.searchParams.delete("guide");
      window.history.replaceState(window.history.state, "", url.pathname + (url.search || ""));
    } catch {}
    try {
      if (window.self !== window.top) {
        window.parent.postMessage({ type: "slicedesk:module-query", params: { guide: guide && guide.id ? String(guide.id) : null } }, "*");
      }
    } catch {}
  }, [guide]);
  const [filedTicket, setFiledTicket] = useState(null);
  const [ticketDraft, setTicketDraftState] = useState(null);
  const [ticketDraftKey, setTicketDraftKey] = useState(0);
  // Opening a report is a page of its own now (was an overlay): every caller
  // that sets a draft also moves to the report stage.
  const setTicketDraft = (d) => {
    setTicketDraftState(d);
    if (d) { setTicketDraftKey((k) => k + 1); setStage('report'); }
  };
  // Which tab the Tickets page opens on — "mine" (My Tickets) or "approvals".
  // Set by the account-menu entries before navigating so each lands on its tab.
  // The bumped nav counter keys the page so re-picking the same menu item (even
  // while already on the page) remounts it onto the chosen tab with fresh data.
  const [ticketsTab, setTicketsTab] = useState("mine");
  const [ticketsNav, setTicketsNav] = useState(0);
  const openTickets = (tab = "mine") => { setTicketsTab(tab); setTicketsNav((n) => n + 1); setStage("tickets"); };
  // Deep-link: `/portal/?ticket=TKT-0042` (the "View your ticket" links in IT
  // Service Desk emails) opens that ticket. Stash the number BEFORE openTickets()
  // rewrites the address bar, then land on the Tickets page — MyTicketsView picks
  // it up and opens it. Survives login: main.jsx keeps ?ticket through the SSO
  // ?next= round-trip, so the user returns straight to the ticket after signing in.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const tnum = new URLSearchParams(window.location.search).get("ticket");
    if (!tnum) return;
    window.__PORTAL_OPEN_TICKET__ = tnum;
    openTickets("mine");
  }, []);
  // Deep-link: land on the request page when `?item=N` came in on a non-/request
  // path (e.g. /portal/?item=5). setStage pushes the /request path; the modal's
  // URL-sync effect re-adds ?item once the form opens.
  React.useEffect(() => {
    if (catalogReq && catalogReq.itemId != null) setStage("request");
    // One-shot on mount — catalogReq here is only ever the URL-seeded value.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Catalog request modal raised from the chat flow (App-level so the answer
  // page can open it). { itemId } preselects the matched app's request form.
  // Deep-link: `?item=N` (any path) opens that catalog item's request form
  // directly — the URL is read once here, and CatalogRequestModal keeps it in
  // sync while a form is open so the address bar is always shareable.
  const [catalogReq, setCatalogReq] = useState(() => {
    if (typeof window === "undefined") return null;
    const id = new URLSearchParams(window.location.search).get("item");
    return id ? { itemId: id } : null;
  });
  // "Request something" is its own page now (stage 'request'), not a modal.
  // Remember which stage we opened it from so closing returns there.
  const openCatalog = (opts = {}) => { setCatalogReq(opts || {}); setStage('request'); };
  // Cache the service catalog for the session so chat-intent matching doesn't
  // refetch on every ticket click.
  const catalogCacheRef = React.useRef(null);
  const loadCatalogOnce = React.useCallback(async () => {
    if (catalogCacheRef.current) return catalogCacheRef.current;
    try {
      const r = await fetch('/api/catalog', { credentials: 'include', cache: 'no-store' });
      const j = r.ok ? await r.json() : null;
      const items = catalogItemsFrom(j);
      catalogCacheRef.current = items;
      return items;
    } catch { return []; }
  }, []);
  // null = modal closed. {} = open with empty drop-zone. { file, note } = open
  // pre-loaded so analysis kicks off automatically (the new "paperclip in the
  // hero input" flow uses this — user attaches + types, hits enter, lands
  // straight on the analyzing phase with their note as context).
  const [screenshotInit, setScreenshotInit] = useState(null);
  const openScreenshot = (init) => setScreenshotInit(init || {});
  const closeScreenshot = () => setScreenshotInit(null);
  const [searchResult, setSearchResult] = useState({ query: '', citations: [], loading: false });

  const runSearch = async (searchQuery, options = {}) => {
    const displayQuery = options.displayQuery || searchQuery;
    setQuery(displayQuery);
    setSearchResult({ query: displayQuery, citations: [], loading: true });
    setStage('search-results');
    try {
      const r = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: searchQuery }),
      });
      const j = await r.json();
      setSearchResult({
        query: displayQuery,
        citations: j.citations || [],
        suggestions: j.suggestions || [],
        answer: j.answer,
        mode: j.mode,
        chat_log_id: j.chat_log_id,
        loading: false,
      });
    } catch (e) {
      setSearchResult({ query: displayQuery, citations: [], loading: false, error: e.message });
    }
  };

  const onQuestionsDone = (outcome) => {
    setOutcome(outcome);
    const parts = Object.values(outcome.answers || {})
      .map((v) => (Array.isArray(v) ? v.join(' ') : v))
      .filter((v) => typeof v === 'string' && v.trim().length > 0);
    const augmented = parts.length > 0 ? `${query}. ${parts.join('. ')}` : query;
    runSearch(augmented, { displayQuery: query });
  };

  const goHome = () => { setStage("landing"); setQuery(""); setOutcome(null); setSearchResult({ query: '', citations: [], loading: false }); };
  // Bumped on every new question so the answer page remounts fresh even when
  // the same text is asked twice.
  const [askKey, setAskKey] = useState(0);
  // Deep link: /portal/help?q=… opens the answer page for that question.
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const url = new URL(window.location.href);
    const qp = url.searchParams.get("q");
    if (qp && qp.trim()) {
      setQuery(qp.trim().slice(0, 500)); setStage("ask");
      // One-shot: drop it from the address bar so a later reload (on another
      // page) doesn't reopen this question.
      if (!IS_EMBEDDED) {
        url.searchParams.delete("q");
        try { window.history.replaceState(window.history.state, "", url.pathname + url.search + url.hash); } catch {}
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Where a typed question should land. A clear app request goes straight to
  // that app's request page — no answer page in between; a request we can't
  // pin to one app opens the catalog already searched for it. Everything else
  // gets an answer (with the quick questions first when they're needed).
  const submitQuestion = async (q) => {
    const text = String(q || '').trim();
    if (!text) return;
    const det = detectAccessRequest(text);
    const wantsSomething = det.isRequest || /\b(need|want|get|request|install|licen[cs]e|seat|account for|access)\b/i.test(text);
    if (!det.isProblem && wantsSomething) {
      const catalog = await loadCatalogItemsOnce();
      const m = matchCatalogItem(catalog, text);
      if (m.strong) { openCatalog({ itemId: m.best.id }); return; }
      if (det.isRequest && m.candidates.length) { openCatalog({ query: (m.terms || []).join(' ') || text.slice(0, 60) }); return; }
    }
    setQuery(text); setAskKey((k) => k + 1); setStage("ask");
  };
  const openTicketNumber = (num) => {
    try { window.__PORTAL_OPEN_TICKET__ = num; } catch {}
    openTickets("mine");
  };
  // "Still need help" from the answer page: a ticket written the way a person
  // would — the question, the follow-ups, and what was already suggested — so
  // the IT Team starts where the conversation ended instead of from scratch.
  const openTicketFromAsk = ({ turns = [], reasons = [], app = null, triage = [] } = {}) => {
    const firstQ = String((turns[0] && turns[0].q) || query || '').trim();
    const more = turns.slice(1).map((t) => t.q).filter(Boolean);
    const tried = [...new Set(turns.flatMap((t) => t.citations || []))].slice(0, 5);
    const blocks = [/[.!?]$/.test(firstQ) ? firstQ : firstQ + '.'];
    if (triage.length) blocks.push(triage.map((p) => `${p.label} — ${p.answer}`).join('\n'));
    if (more.length) blocks.push('More detail:\n' + more.map((m) => '- ' + m).join('\n'));
    if (tried.length) blocks.push('The IT Hub suggested these guides, but they didn’t solve it:\n' + tried.map((g) => '- ' + g).join('\n'));
    if (reasons.length) blocks.push('What didn’t work: ' + reasons.join(', ') + '.');
    const det = detectAccessRequest([firstQ, ...more].join('. '));
    setTicketDraft({
      subject: (app && det.isRequest && !det.isProblem ? 'Access request: ' : '') + firstQ.slice(0, 140),
      description: blocks.join('\n\n'),
      type: det.isRequest && !det.isProblem ? 'service_request' : 'incident',
      priority: 'medium',
    });
  };
  // Screenshot → ticket. This used to show a "Ticket filed" toast WITHOUT
  // creating anything, so people believed IT had their screenshot when no
  // ticket existed. Now it opens the real ticket form, pre-filled with the
  // diagnosis and the screenshot attached, for the person to send.
  const openTicketFromScreenshot = async (ctx = {}) => {
    let files = [];
    try {
      if (ctx.file && ctx.file.dataUrl) {
        const blob = await (await fetch(ctx.file.dataUrl)).blob();
        files = [new File([blob], ctx.file.name || 'screenshot.png', { type: blob.type || 'image/png' })];
      }
    } catch { /* the form still opens; they can re-attach */ }
    const note = String(ctx.note || '').trim();
    const lines = [];
    if (note) lines.push(/[.!?]$/.test(note) ? note : note + '.');
    if (ctx.diagnosis) lines.push('What the screenshot shows: ' + ctx.diagnosis);
    if (Array.isArray(ctx.clues) && ctx.clues.length) lines.push('Details spotted:\n' + ctx.clues.map((c) => '- ' + c).join('\n'));
    if (Array.isArray(ctx.steps) && ctx.steps.length) lines.push('Suggested steps (didn’t solve it):\n' + ctx.steps.map((c, i) => `${i + 1}. ${c}`).join('\n'));
    setTicketDraft({
      subject: (note || ctx.diagnosis || 'Issue shown in screenshot').slice(0, 140),
      description: lines.join('\n\n') || 'See the attached screenshot.',
      type: 'incident',
      priority: ctx.is_hardware_issue ? 'high' : 'medium',
      files,
    });
  };

  // Assemble a clean, plain-text ticket from everything captured this session:
  // the question, the clarifying answers (mapped from option ids back to their
  // human labels), and the assistant's suggestion + guides — so the user just
  // reviews and submits, no re-typing. The ticket system renders the body as
  // plain text, so we avoid markdown (no **, no [N] citations).
  const openTicket = async (ctx = {}) => {
    const issue = String(query || '').trim();

    const qs = (outcome && outcome.route && outcome.route.questions) || [];
    const answers = (outcome && outcome.answers) || {};
    const labelFor = (q, id) => {
      const opt = (q.options || []).find((o) => o.id === id);
      return opt ? opt.label : id;
    };
    const details = qs.map((q) => {
      const a = answers[q.id];
      if (a == null || a === '' || (Array.isArray(a) && a.length === 0)) return null;
      const val = Array.isArray(a)
        ? a.map((id) => labelFor(q, id)).join(', ')
        : (q.type === 'text' ? String(a) : labelFor(q, a));
      return val && String(val).trim() ? `${q.label} — ${String(val).trim()}` : null;
    }).filter(Boolean);

    // Write it the way a person would: the issue in their own words, then the
    // follow-up answers as plain lines — no headers, bullets, guides or meta.
    const opener = issue ? (/[.!?]$/.test(issue) ? issue : issue + '.') : 'I need some help.';
    const blocks = [opener];
    if (details.length) blocks.push(details.join('\n'));
    const body = blocks.join('\n\n');
    const fullText = [issue].concat(details).join('. ');
    const det = detectAccessRequest(fullText);

    // The "two logics": an access/service request vs a broken-thing issue.
    // Explicit access phrasing (and no "broken" signal) → route into the service
    // catalog when we can identify the app, so it follows the proper request +
    // approval flow; otherwise open the review card as a service request.
    if (det.isRequest && !det.isProblem) {
      const m = matchCatalogItem(await loadCatalogOnce(), fullText);
      if (m.strong) { openCatalog({ itemId: m.best.id }); return; }
      // Not sure which app, but sure it IS an app request: open the catalog
      // seeded with the distinctive words, so the ranked shortlist is already
      // on screen. Previously this fell through to a freeform ticket, which
      // is how a request for an app the catalog *does* carry ended up as an
      // untagged ticket someone had to reclassify by hand later.
      if (m.candidates.length) {
        openCatalog({ query: m.terms.join(' ') || fullText.slice(0, 60) });
        return;
      }
      setTicketDraft({
        subject: issue ? ('Access request: ' + issue.slice(0, 120)) : 'Access / service request',
        description: body,
        type: 'service_request',
        priority: 'medium',
      });
      return;
    }

    // A named catalog app with a light request verb (e.g. "I need Figma") also
    // routes to the catalog, as long as it isn't phrased as a problem.
    if (!det.isProblem && /\b(need|want|get|use|access|add|request|set up|sign up|new)\b/.test(fullText.toLowerCase())) {
      // No phrasing that says "this is a request", so only a confident app
      // match may hijack the route — otherwise fall through to the normal
      // support path below rather than guessing.
      const m = matchCatalogItem(await loadCatalogOnce(), fullText);
      if (m.strong) { openCatalog({ itemId: m.best.id }); return; }
    }

    setTicketDraft({
      subject: issue ? issue.slice(0, 140) : 'IT support request',
      description: body,
      type: 'incident',
      priority: 'medium',
    });
  };
  // Scroll to top whenever we change pages — otherwise clicking nav while scrolled
  // leaves the new page offscreen and users think it didn't navigate.
  useScrollToTop([stage]);
  const navActive = stage === "knowledge" ? "Knowledge"
    : stage === "status" ? "Status"
    : (stage === "tickets" || stage === "report" || stage === "request") ? "My Tickets"
    : "Help";
  const onNavigate = (label) => {
    if (label === "Knowledge") setStage("knowledge");
    else if (label === "Status") setStage("status");
    else if (label === "My Tickets") openTickets("mine");
    else if (label === "Help") goHome();
  };

  useEffect(() => {
    document.documentElement.setAttribute("data-gesture", tweaks.gesture);
  }, [tweaks.gesture]);

  const voiceOptions = [
  { value: "concierge", label: "Concierge" },
  { value: "precise", label: "Precise" },
  { value: "playful", label: "Playful" }];

  const gestureOptions = [
  { value: "still", label: "Still" },
  { value: "smooth", label: "Smooth" },
  { value: "springy", label: "Springy" }];

  const guideStyleOptions = [
  { value: "guided", label: "Guided mode" },
  { value: "legacy", label: "Side sheet" }];


  return (
    <TweakCtx.Provider value={tweaks}>
      <GlobalKeyframes />
      <Nav onHome={() => { setGuide(null); goHome(); }} onNavigate={(l) => { setGuide(null); onNavigate(l); }} active={navActive} onOpenNotifications={() => setStage("notifications")} onOpenTickets={() => openTickets("mine")} onOpenApprovals={() => openTickets("approvals")} />


      {/* __PORTAL2_SCROLL_WRAP_OPEN__ */}
      <div className="page-scroll">

      {stage === "landing" &&
      <Landing
        onSubmit={submitQuestion}
        onOpenStatus={() => setStage("status")}
        onOpenKnowledge={() => setStage("knowledge")}
        onOpenGuide={(g) => setGuide(g)}
        onOpenTickets={() => openTickets("mine")}
        onOpenTicketNumber={openTicketNumber}
        onOpenScreenshot={(init) => openScreenshot(init)}
        onRequestItem={(id) => openCatalog({ itemId: id })}
        onBrowseCatalog={(q) => openCatalog(q ? { query: q } : {})}
        onCustomRequest={(t) => openCatalog({ custom: t || '' })}
        onRequest={() => openCatalog()} />
      }

      {stage === "ask" && query &&
      <AskPage
        key={askKey}
        query={query}
        onBack={goHome}
        onOpenGuide={(g) => setGuide(g)}
        onRequestItem={(id) => openCatalog({ itemId: id })}
        onBrowseCatalog={(q) => openCatalog(q ? { query: q } : {})}
        onOpenStatus={() => setStage("status")}
        onOpenTicketNumber={openTicketNumber}
        onFileTicket={openTicketFromAsk}
        onScreenshot={(note) => openScreenshot({ note })} />
      }

      {stage === "questions" &&
      <QuestionFlow
        query={query}
        onBack={() => setStage("landing")}
        onDone={onQuestionsDone} />
      }

      {stage === "search-results" &&
      <HubSearchResults
        query={searchResult.query}
        citations={searchResult.citations}
        suggestions={searchResult.suggestions}
        answer={searchResult.answer}
        mode={searchResult.mode}
        chatLogId={searchResult.chat_log_id}
        loading={searchResult.loading}
        onBack={goHome}
        onOpenGuide={(g) => setGuide(g)}
        onFileTicket={() => openTicket({ source: 'answer' })} />
      }

      {stage === "knowledge" &&
      <KnowledgePage onBack={goHome} onOpenGuide={(g) => setGuide(g)} />
      }

      {stage === "status" &&
      <StatusPage onBack={goHome} />
      }

      {stage === "tickets" &&
      <TicketsPage
        key={ticketsNav}
        initialTab={ticketsTab}
        onBack={goHome}
        onReportIssue={() => setTicketDraft({ subject: "", description: "", type: "incident", priority: "medium" })}
        onRequest={() => openCatalog()} />
      }

      {stage === "report" && ticketDraft &&
      <NewTicketModal
        asPage
        key={ticketDraftKey}
        draft={ticketDraft}
        // Back / Cancel land on My Tickets, like the catalog page.
        onClose={() => { setTicketDraft(null); openTickets("mine"); }}
        onCreated={() => { setTicketDraft(null); openTickets("mine"); }}
        onBrowseCatalog={() => { setTicketDraft(null); openCatalog({}); }} />
      }

      {stage === "request" &&
      <CatalogRequestModal
        asPage
        initialItemId={catalogReq && catalogReq.itemId}
        initialCustom={catalogReq && catalogReq.custom != null ? catalogReq.custom : null}
        initialQuery={catalogReq && catalogReq.query}
        // Back (and Cancel) land on My Tickets — where requests live — rather
        // than wherever the catalog was opened from.
        onClose={() => openTickets("mine")}
        onCreated={() => openTickets("mine")} />
      }

      {stage === "notifications" &&
      <NotificationsPage onBack={goHome} onOpenTickets={() => openTickets("mine")} />
      }

      {/* Footer hidden on working surfaces — those flows have short content
          and the Footer would float in the middle of the viewport. Marketing
          surfaces (Help / Knowledge / Status) keep it. */}
      {/* Inside SliceDesk (module iframe) the platform shows its own badge —
          only the standalone IT portal shows "Built by the Slice IT team". */}
      {!IS_EMBEDDED && stage !== "notifications"
        && stage !== "questions" && stage !== "search-results"
        // The answer page pins its follow-up composer to the bottom; the
        // footer badge would scroll up underneath it.
        && stage !== "ask"
        && (
        <Footer />
      )}

      </div>
      {/* __PORTAL2_SCROLL_WRAP_CLOSE__ */}

      <TweaksPanel>
        <TweakSection label="Voice" />
        <TweakRadio label="Tone" value={tweaks.voice} options={voiceOptions}
        onChange={(v) => setTweaksState("voice", v)} />
        <div style={{ fontSize: 10.5, color: "rgba(41,38,27,.5)", lineHeight: 1.4, marginTop: -4 }}>
          {tweaks.voice === "concierge" && "Warm, first‑name, hospitable."}
          {tweaks.voice === "precise" && "Direct utility. No warm‑up."}
          {tweaks.voice === "playful" && "Friendly with character."}
        </div>
        <TweakSection label="Gesture" />
        <TweakRadio label="Motion" value={tweaks.gesture} options={gestureOptions}
        onChange={(v) => setTweaksState("gesture", v)} />
        <div style={{ fontSize: 10.5, color: "rgba(41,38,27,.5)", lineHeight: 1.4, marginTop: -4 }}>
          {tweaks.gesture === "still" && "Animations off. Instant."}
          {tweaks.gesture === "smooth" && "Measured ease-out. Always."}
          {tweaks.gesture === "springy" && "Bouncy overshoot, toy‑like."}
        </div>
        <TweakSection label="Help guide" />
        <TweakRadio label="Step-by-step UI" value={tweaks.guideStyle} options={guideStyleOptions}
        onChange={(v) => setTweaksState("guideStyle", v)} />
        <div style={{ fontSize: 10.5, color: "rgba(41,38,27,.5)", lineHeight: 1.4, marginTop: -4 }}>
          {tweaks.guideStyle === "guided" && "Full-screen, one step at a time, with progress + branches."}
          {tweaks.guideStyle === "legacy" && "Original side sheet — all steps in one scroll."}
        </div>
      </TweaksPanel>

      {screenshotInit && (
        <ScreenshotHelper
          initialFile={screenshotInit.file}
          initialNote={screenshotInit.note || ''}
          onClose={closeScreenshot}
          onOpenGuide={(g) => { setGuide(g); }}
          onFileTicket={(ctx) => { closeScreenshot(); openTicketFromScreenshot(ctx); }}
        />
      )}

      {guide && (tweaks.guideStyle === "legacy"
        ? <GuideSheet guide={guide} onClose={() => setGuide(null)} />
        : <GuideExperience
            guide={guide}
            fromQuery={query}
            onClose={() => setGuide(null)}
            onFileTicket={(ctx) => {
              // "File a ticket →" from a guide: close the guide, go to My Tickets,
              // and open the report-issue form prefilled with the guide + the
              // feedback the user just gave (what was off / their note).
              const c = ctx || {};
              const reasons = Array.isArray(c.reasons) ? c.reasons : [];
              const parts = [];
              if (c.guideTitle) parts.push(`I followed the guide “${c.guideTitle}” but it didn't resolve my issue.`);
              if (reasons.length) parts.push(`What was off: ${reasons.join(', ')}.`);
              if (c.note) parts.push(c.note);
              setGuide(null);
              openTickets('mine');
              setTicketDraft({
                subject: c.guideTitle ? `Still stuck after: ${c.guideTitle}` : '',
                description: parts.join('\n\n'),
                type: 'incident', priority: 'medium',
              });
            }}
            onOpenGuide={(g) => setGuide(g)}
            onOpenScreenshot={() => openScreenshot()}
          />)}
      {filedTicket && <FiledToast ticket={filedTicket} onClose={() => setFiledTicket(null)} onView={() => setFiledTicket(null)} />}
    </TweakCtx.Provider>);

}

