// ─── misc (c0c64165) ──────────────────────────────────
// ====================================================================
//  Slice IT Hub — Screenshot AI helper
//  "Drop a screenshot of what you're seeing, AI tells you what to do."
//  Used both standalone (from landing) and inline within Guided Mode.
// ====================================================================

// (hooks already destructured at top of file)

// --------------------------------------------------------------------
//  Real screenshot analysis — POSTs the image to /api/help/screenshot,
//  which routes it through Claude vision with the live KB title list as
//  grounding so suggestions point at real guides instead of inventing them.
//  Returns the server's already-validated payload (or throws so the UI can
//  surface the failure cleanly).
// --------------------------------------------------------------------
async function analyzeScreenshot({ dataUrl, note = "" }) {
  if (!dataUrl) throw new Error('Missing screenshot data URL');
  const r = await fetch('/api/help/screenshot', {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ imageDataUrl: dataUrl, note }),
  });
  if (!r.ok) {
    let detail = `HTTP ${r.status}`;
    try { const j = await r.json(); detail = j.error || j.detail || detail; } catch {}
    throw new Error(detail);
  }
  return r.json();
}

// --------------------------------------------------------------------
//  ScreenshotHelper — modal with three states: empty → analyzing → result
// --------------------------------------------------------------------
function ScreenshotHelper({ onClose, onOpenGuide, onFileTicket, initialNote = "", initialFile = null }) {
  const [phase, setPhase] = useState("empty"); // 'empty' | 'analyzing' | 'result'
  const [file, setFile] = useState(initialFile); // { name, dataUrl }
  const [note, setNote] = useState(initialNote);
  const [dragOver, setDragOver] = useState(false);
  const [pasted, setPasted] = useState(false);
  const [result, setResult] = useState(null);
  const [progress, setProgress] = useState(0);
  const fileInputRef = useRef(null);
  // When the parent opened the modal with a file already attached (the
  // hero-input flow), kick analysis off immediately instead of forcing the
  // user through the empty drop zone first. The flag stays low so subsequent
  // file replacements via the in-modal picker still go through the manual
  // "Analyze" button.
  const autoStartedRef = useRef(false);

  // Esc to close
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  // Listen for paste anywhere in the modal
  useEffect(() => {
    const onPaste = (e) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      for (const item of items) {
        if (item.type.startsWith("image/")) {
          const blob = item.getAsFile();
          handleFile(blob, "pasted-screenshot.png");
          setPasted(true);
          setTimeout(() => setPasted(false), 1500);
          break;
        }
      }
    };
    window.addEventListener("paste", onPaste);
    return () => window.removeEventListener("paste", onPaste);
  }, []);

  const handleFile = useCallback((blob, fallbackName) => {
    if (!blob) return;
    if (!blob.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      setFile({ name: blob.name || fallbackName || "screenshot.png", dataUrl: e.target.result });
    };
    reader.readAsDataURL(blob);
  }, []);

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    const f = e.dataTransfer.files?.[0];
    if (f) handleFile(f);
  };

  const onPick = (e) => {
    const f = e.target.files?.[0];
    if (f) handleFile(f);
  };

  const removeFile = () => { setFile(null); setResult(null); setPhase("empty"); };

  const [error, setError] = useState(null);

  const runAnalysis = async () => {
    if (!file) return;
    setPhase("analyzing");
    setProgress(0);
    setError(null);
    // Soft progress bar while the vision call is in flight — capped at 92%
    // until the response actually arrives.
    let p = 0;
    const tick = setInterval(() => {
      p += 6 + Math.random() * 10;
      setProgress(Math.min(p, 92));
    }, 220);
    try {
      const r = await analyzeScreenshot({ dataUrl: file.dataUrl, note });
      clearInterval(tick);
      setProgress(100);
      setResult(r);
      setPhase("result");
    } catch (err) {
      clearInterval(tick);
      setProgress(0);
      setError(err.message || 'Analysis failed');
      setPhase("empty");
    }
  };

  const openGuide = (g) => {
    if (!g || !onOpenGuide) return;
    onOpenGuide({ id: g.id, title: g.title, category: g.category });
    onClose();
  };
  const openSuggestedGuide = () => {
    const first = result?.guide_suggestions?.[0];
    if (first) openGuide(first);
  };

  // Auto-start analysis when the modal mounts with a pre-attached file (the
  // hero-input "paperclip in chat" flow). Guarded so we run it exactly once.
  useEffect(() => {
    if (autoStartedRef.current) return;
    if (initialFile && file && phase === "empty") {
      autoStartedRef.current = true;
      runAnalysis();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex: 110,
        background: "rgba(33,30,30,0.45)", backdropFilter: "blur(6px)",
        animation: "ssIn .25s var(--ease) both",
        display: "flex", alignItems: "flex-start", justifyContent: "center",
        padding: "60px 24px 40px",
        overflowY: "auto",
      }}
    >
      <style>{`
        @keyframes ssIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes ssPanelIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
        @keyframes scanLine {
          0% { transform: translateY(-4%); opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { transform: translateY(104%); opacity: 0; }
        }
        @keyframes pulseBox {
          0%, 100% { box-shadow: 0 0 0 0 rgba(253,200,49,0.6); }
          50% { box-shadow: 0 0 0 8px rgba(253,200,49,0); }
        }
        .ss-action-btn { transition: transform .15s, box-shadow .15s; }
        .ss-action-btn:hover { transform: translate(0, 0); box-shadow: 0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28); }
        .ss-action-btn:active { transform: translate(0, 0); box-shadow: 0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28); }
      `}</style>

      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "min(720px, 100%)",
          background: "#FFF9E6",
          border: "1px solid #211E1E",
          borderRadius: 14,
          boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
          padding: 0,
          animation: "ssPanelIn .35s var(--ease) both",
          overflow: "hidden",
        }}
      >
        {/* Header */}
        <div style={{
          padding: "20px 28px",
          borderBottom: "1px solid #211E1E",
          background: "#FDC831",
          display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{
              width: 36, height: 36, borderRadius: 8,
              background: "#211E1E", color: "#FDC831",
              border: "1px solid #211E1E",
              display: "grid", placeItems: "center",
              fontFamily: "Archivo, sans-serif",
              fontSize: 18, fontWeight: 900,
            }}>📷</div>
            <div>
              <div style={{
                fontFamily: "var(--font-mono)",
                fontSize: 10.5, fontWeight: 600,
                letterSpacing: "0.08em", textTransform: "uppercase",
                color: "#4A3F2E",
              }}>Show, don't type</div>
              <div style={{
                fontFamily: "var(--font-head)",
                fontSize: 19, fontWeight: 400, color: "#211E1E",
                letterSpacing: "-0.01em",
              }}>
                Add a screenshot — we'll take a look
              </div>
            </div>
          </div>
          <button onClick={onClose} aria-label="Close" style={{
            width: 32, height: 32,
            background: "#FFFFFF",
            border: "1px solid #211E1E", borderRadius: 4,
            boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
            display: "grid", placeItems: "center",
            color: "#211E1E", cursor: "pointer",
            fontFamily: "Archivo, sans-serif",
            fontSize: 16, fontWeight: 900,
          }}>×</button>
        </div>

        <div style={{ padding: "26px 28px 28px" }}>
          {phase === "empty" && (
            <>
              {/* Drop zone */}
              <label
                htmlFor="ss-file-input"
                onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                onDragLeave={() => setDragOver(false)}
                onDrop={onDrop}
                style={{
                  display: "block",
                  background: dragOver ? "#FDC831" : "#FFFFFF",
                  border: `2.5px dashed ${dragOver ? "#211E1E" : "rgba(33,30,30,0.4)"}`,
                  borderRadius: 12,
                  padding: file ? "0" : "44px 24px",
                  textAlign: "center",
                  cursor: "pointer",
                  transition: "background .2s, border-color .2s",
                  position: "relative",
                  overflow: "hidden",
                  animation: pasted ? "pulseBox .9s ease" : "none",
                }}
              >
                {file ? (
                  <div style={{ position: "relative" }}>
                    <img
                      src={file.dataUrl}
                      alt="screenshot preview"
                      style={{
                        width: "100%",
                        maxHeight: 320,
                        objectFit: "contain",
                        background: "#211E1E",
                        display: "block",
                      }}
                    />
                    <button
                      onClick={(e) => { e.preventDefault(); e.stopPropagation(); removeFile(); }}
                      style={{
                        position: "absolute", top: 10, right: 10,
                        padding: "6px 10px",
                        background: "#FFFFFF",
                        border: "1px solid #211E1E", borderRadius: 4,
                        boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
                        fontFamily: "var(--font-mono)",
                        fontSize: 11, fontWeight: 600,
                        letterSpacing: "0.04em", textTransform: "uppercase",
                        color: "#211E1E", cursor: "pointer",
                      }}
                    >
                      Remove
                    </button>
                    <div style={{
                      position: "absolute", bottom: 0, left: 0, right: 0,
                      padding: "8px 12px",
                      background: "rgba(33,30,30,0.9)",
                      color: "#FDC831",
                      fontFamily: "ui-monospace, SF Mono, Menlo, monospace",
                      fontSize: 11.5,
                      textAlign: "left",
                    }}>
                      {file.name}
                    </div>
                  </div>
                ) : (
                  <>
                    <div style={{
                      width: 56, height: 56, borderRadius: 12,
                      background: dragOver ? "#211E1E" : "#FDC831",
                      color: dragOver ? "#FDC831" : "#211E1E",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      margin: "0 auto 14px",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 28, fontWeight: 900,
                      transition: "background .2s, color .2s",
                    }}>↑</div>
                    <div style={{
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 17, fontWeight: 800, color: "#211E1E",
                      marginBottom: 6, letterSpacing: "-0.012em",
                    }}>
                      {dragOver ? "Drop it!" : "Drag a screenshot here"}
                    </div>
                    <div style={{ fontSize: 13, color: "#4A3F2E", lineHeight: 1.5 }}>
                      or <span style={{ textDecoration: "underline", fontWeight: 700 }}>browse files</span>
                      {" · "}
                      paste with <kbd style={kbd}>⌘V</kbd> / <kbd style={kbd}>Ctrl V</kbd>
                    </div>
                  </>
                )}
                <input
                  id="ss-file-input"
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={onPick}
                  style={{ display: "none" }}
                />
              </label>

              {/* Optional note */}
              <div style={{ marginTop: 18 }}>
                <label style={{
                  display: "block",
                  fontFamily: "var(--font-mono)",
                  fontSize: 10.5, fontWeight: 600,
                  letterSpacing: "0.06em", textTransform: "uppercase",
                  color: "#4A3F2E", marginBottom: 6,
                }}>
                  Optional note <span style={{ fontWeight: 600, color: "#78684C" }}>· what's going wrong?</span>
                </label>
                <textarea
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  rows={2}
                  placeholder="e.g. Slack won't sign in, this is what I see"
                  style={{
                    width: "100%",
                    background: "#FFFFFF",
                    border: "1px solid #211E1E",
                    borderRadius: 8,
                    padding: "10px 12px",
                    fontFamily: "inherit",
                    fontSize: 14,
                    color: "#211E1E",
                    resize: "vertical",
                    outline: "none",
                  }}
                />
              </div>

              {/* Privacy note + CTA */}
              <div style={{
                marginTop: 18,
                display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12,
                flexWrap: "wrap",
              }}>
                <div style={{ fontSize: 11.5, color: "#4A3F2E", lineHeight: 1.45, maxWidth: 360 }}>
                  <strong style={{ color: "#211E1E" }}>Private.</strong> Your screenshot stays in this session — it isn't stored unless you file a ticket.
                </div>
                <button
                  onClick={runAnalysis}
                  disabled={!file}
                  className="ss-action-btn"
                  style={{
                    padding: "12px 22px",
                    background: file ? "#211E1E" : "#E0DCCF",
                    color: file ? "#FDC831" : "#78684C",
                    border: `2px solid ${file ? "#211E1E" : "#C9C2B0"}`,
                    borderRadius: 4,
                    boxShadow: file ? "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)" : "none",
                    fontFamily: "var(--font-mono)",
                    fontWeight: 600, fontSize: 13,
                    letterSpacing: "0.04em", textTransform: "uppercase",
                    cursor: file ? "pointer" : "not-allowed",
                    display: "inline-flex", alignItems: "center", gap: 8,
                  }}
                >
                  Take a look <span style={{ fontSize: 14 }}>→</span>
                </button>
              </div>
            </>
          )}

          {phase === "analyzing" && (
            <AnalyzingView file={file} progress={progress} />
          )}

          {phase === "result" && result && (
            <ResultView
              file={file}
              result={result}
              onOpenGuide={openSuggestedGuide}
              onOpenSpecificGuide={openGuide}
              onFileTicket={() => {
                onFileTicket?.({
                  file,
                  note,
                  diagnosis: result.diagnosis,
                  clues: result.clues,
                  steps: result.next_steps,
                  is_hardware_issue: result.is_hardware_issue,
                });
                onClose();
              }}
              onRetry={() => { setPhase("empty"); setResult(null); setError(null); }}
            />
          )}

          {/* Error banner — surfaced when the vision call fails so the user
              isn't left staring at a stalled progress bar. Stays on the empty
              phase so they can retry or remove the file. */}
          {error && phase === "empty" && (
            <div style={{
              marginTop: 14,
              padding: "10px 14px",
              background: "#FFE8E5",
              border: "1px solid #DA3327",
              borderRadius: 8,
              fontSize: 12.5, color: "#7A1A14", fontWeight: 600,
              lineHeight: 1.45,
            }}>
              <div>Couldn't analyze this screenshot — {error}.</div>
              {/* Don't strand them: the screenshot is still the most useful
                  thing they can send, so offer to send it as-is. */}
              {file && (
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10 }}>
                  <button type="button" className="ask-btn is-primary" style={{ minHeight: 34 }}
                    onClick={() => { onFileTicket?.({ file, note }); onClose(); }}>
                    Send it to IT anyway
                  </button>
                  <button type="button" className="ask-btn" style={{ minHeight: 34 }} onClick={() => { setError(null); }}>Try again</button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

const kbd = {
  display: "inline-block",
  padding: "1px 5px",
  fontFamily: "ui-monospace, SF Mono, Menlo, monospace",
  fontSize: 10.5,
  background: "#FFFFFF",
  border: "1px solid rgba(33,30,30,0.3)",
  borderRadius: 3,
  color: "#211E1E",
  fontWeight: 600,
};

// --------------------------------------------------------------------
//  AnalyzingView — image with scanning line + streamed status
// --------------------------------------------------------------------
function AnalyzingView({ file, progress }) {
  const stages = [
    { at: 10,  label: "Reading the image…" },
    { at: 35,  label: "Identifying app and error state…" },
    { at: 65,  label: "Cross-referencing common fixes…" },
    { at: 90,  label: "Picking the right guide…" },
  ];
  const current = [...stages].reverse().find(s => progress >= s.at) || stages[0];

  return (
    <div>
      <div style={{
        position: "relative",
        background: "#211E1E",
        border: "1px solid #211E1E",
        borderRadius: 12,
        overflow: "hidden",
        marginBottom: 18,
      }}>
        <img
          src={file?.dataUrl}
          alt=""
          style={{
            width: "100%",
            maxHeight: 280,
            objectFit: "contain",
            display: "block",
            opacity: 0.85,
          }}
        />
        {/* Scanning line */}
        <div style={{
          position: "absolute", left: 0, right: 0,
          height: 3,
          background: "linear-gradient(90deg, transparent, #FDC831, transparent)",
          boxShadow: "0 0 16px #FDC831",
          animation: "scanLine 1.6s linear infinite",
        }}/>
        {/* Corner markers */}
        {[
          { top: 10, left: 10 }, { top: 10, right: 10 },
          { bottom: 10, left: 10 }, { bottom: 10, right: 10 },
        ].map((pos, i) => (
          <div key={i} style={{
            position: "absolute",
            ...pos,
            width: 14, height: 14,
            border: "1px solid #FDC831",
            borderRadius: 2,
          }}/>
        ))}
      </div>

      {/* Progress bar */}
      <div style={{
        height: 8,
        background: "#FFFFFF",
        border: "1px solid #211E1E",
        borderRadius: 999,
        overflow: "hidden",
        marginBottom: 12,
      }}>
        <div style={{
          height: "100%",
          width: `${progress}%`,
          background: "#211E1E",
          transition: "width .25s var(--ease)",
        }}/>
      </div>

      <div style={{
        fontFamily: "Archivo, sans-serif",
        fontSize: 13.5, fontWeight: 700,
        color: "#211E1E",
        display: "flex", alignItems: "center", gap: 10,
      }}>
        <span style={{
          width: 8, height: 8, borderRadius: "50%",
          background: "#0A8A3E",
          animation: "pulseBox 1.2s ease-in-out infinite",
        }}/>
        {current.label}
      </div>
    </div>
  );
}

// --------------------------------------------------------------------
//  ResultView — diagnosis + suggested guide + next steps + ticket
// --------------------------------------------------------------------
function ResultView({ file, result, onOpenGuide, onOpenSpecificGuide, onFileTicket, onRetry }) {
  const confPct = Math.round((result.confidence || 0) * 100);
  const confTone = result.confidence >= 0.7 ? "high" : (result.confidence >= 0.5 ? "med" : "low");
  const confColor = confTone === "high" ? "#0A8A3E" : (confTone === "med" ? "#B8860B" : "#DA3327");
  const isHardware = result.is_hardware_issue === true;
  const suggestions = Array.isArray(result.guide_suggestions) ? result.guide_suggestions : [];
  const steps = Array.isArray(result.next_steps) ? result.next_steps : [];
  const clues = Array.isArray(result.clues) ? result.clues : [];

  return (
    <div>
      {/* Image thumb + diagnosis */}
      <div style={{ display: "grid", gridTemplateColumns: "120px 1fr", gap: 16, alignItems: "flex-start", marginBottom: 20 }}>
        <div style={{
          width: 120, height: 90,
          background: "#211E1E",
          border: "1px solid #211E1E",
          borderRadius: 8,
          overflow: "hidden",
          flexShrink: 0,
        }}>
          <img src={file?.dataUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
        </div>
        <div>
          <div style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            padding: "3px 10px",
            background: isHardware ? "#211E1E" : confColor,
            color: "#FFFFFF",
            border: `1.5px solid ${isHardware ? "#211E1E" : confColor}`,
            borderRadius: 999,
            fontFamily: "var(--font-mono)",
            fontSize: 10, fontWeight: 600,
            letterSpacing: "0.06em", textTransform: "uppercase",
            marginBottom: 8,
          }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#FFFFFF" }}/>
            {isHardware ? "Hardware issue" : `${confPct}% confident`}
          </div>
          <div style={{
            fontFamily: "var(--font-mono)",
            fontSize: 10.5, fontWeight: 600,
            letterSpacing: "0.06em", textTransform: "uppercase",
            color: "#4A3F2E", marginBottom: 4,
          }}>What we see</div>
          <h3 style={{
            fontFamily: "var(--font-head)",
            fontSize: 22, fontWeight: 400,
            letterSpacing: "-0.01em", lineHeight: 1.15,
            margin: 0, color: "#211E1E",
          }}>
            {result.diagnosis}
          </h3>
        </div>
      </div>

      {/* Hardware short-circuit — replaces Clues + Steps + Guides with one
          clear "go file a ticket" message so users don't try to self-repair
          a damaged device. */}
      {isHardware && (
        <div style={{
          background: "#FFE8E5",
          border: "1px solid #DA3327",
          borderRadius: 10,
          boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
          padding: "16px 18px",
          marginBottom: 18,
        }}>
          <div style={{
            fontFamily: "var(--font-mono)",
            fontSize: 10.5, fontWeight: 600,
            letterSpacing: "0.06em", textTransform: "uppercase",
            color: "#7A1A14", marginBottom: 6,
          }}>Hardware repair — IT Team only</div>
          <div style={{ fontSize: 14, color: "#211E1E", lineHeight: 1.55, marginBottom: 6 }}>
            This looks like physical damage or a hardware failure. Don't try to fix it yourself —
            stop using the device if it's unsafe (battery swelling, smoke, liquid damage), back up
            anything you can still reach, and file a ticket so the <strong>IT Team</strong> can
            inspect it or swap the device.
          </div>
          {clues.length > 0 && (
            <ul style={{ margin: "8px 0 0", paddingLeft: 20, fontSize: 13, color: "#3D1E1B", lineHeight: 1.55 }}>
              {clues.map((c, i) => <li key={i}>{c}</li>)}
            </ul>
          )}
        </div>
      )}

      {/* Clues + Next-steps + Guide suggestions — software path only */}
      {!isHardware && (
        <>
          {clues.length > 0 && (
            <div style={{
              background: "#FFFFFF",
              border: "1px solid #211E1E",
              borderRadius: 8,
              padding: "14px 18px",
              marginBottom: 18,
            }}>
              <div style={{
                fontFamily: "var(--font-mono)",
                fontSize: 10.5, fontWeight: 600,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 8,
              }}>What gave it away</div>
              <ul style={{ margin: 0, paddingLeft: 20, fontSize: 13.5, color: "#211E1E", lineHeight: 1.6 }}>
                {clues.map((c, i) => <li key={i}>{c}</li>)}
              </ul>
            </div>
          )}

          {/* Suggested guides — up to 3, real KB rows. Click opens the guide. */}
          {suggestions.length > 0 && (
            <div style={{ marginBottom: 18 }}>
              <div style={{
                fontFamily: "var(--font-mono)",
                fontSize: 10.5, fontWeight: 600,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 10,
              }}>{suggestions.length === 1 ? "Recommended guide" : "Recommended guides"}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {suggestions.map((g, i) => (
                  <div
                    key={g.id ?? i}
                    onClick={() => onOpenSpecificGuide && onOpenSpecificGuide(g)}
                    className="ss-action-btn"
                    style={{
                      background: i === 0 ? "#FDC831" : "#FFFFFF",
                      border: "1px solid #211E1E",
                      borderRadius: 10,
                      boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
                      padding: "12px 16px",
                      cursor: "pointer",
                      display: "flex", alignItems: "center", gap: 14,
                    }}
                  >
                    <div style={{
                      width: 36, height: 36, borderRadius: 8,
                      background: "#211E1E", color: "#FDC831",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 16, fontWeight: 900,
                      flexShrink: 0,
                    }}>→</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontFamily: "Archivo, sans-serif",
                        fontSize: 15, fontWeight: 800,
                        color: "#211E1E", letterSpacing: "-0.01em",
                      }}>{g.title}</div>
                      {(g.reason || g.category) && (
                        <div style={{ fontSize: 12, color: "#4A3F2E", marginTop: 2, lineHeight: 1.4 }}>
                          {g.reason || g.category}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* What to try */}
          {steps.length > 0 && (
            <div style={{ marginBottom: 22 }}>
              <div style={{
                fontFamily: "var(--font-mono)",
                fontSize: 10.5, fontWeight: 600,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 10,
              }}>Try this in order</div>
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {steps.map((s, i) => (
                  <li key={i} style={{
                    display: "grid", gridTemplateColumns: "26px 1fr",
                    gap: 12, padding: "8px 0",
                    borderBottom: i < steps.length - 1 ? "1px dashed rgba(33,30,30,0.18)" : "none",
                  }}>
                    <div style={{
                      width: 22, height: 22, borderRadius: "50%",
                      background: "#FFFFFF",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 11, fontWeight: 800,
                      color: "#211E1E",
                      flexShrink: 0,
                    }}>{i + 1}</div>
                    <div style={{ fontSize: 14, color: "#211E1E", lineHeight: 1.5, paddingTop: 1 }}>
                      {s}
                    </div>
                  </li>
                ))}
              </ol>
            </div>
          )}
        </>
      )}

      {/* Footer actions */}
      <div style={{
        display: "flex", gap: 10, justifyContent: "space-between", alignItems: "center", flexWrap: "wrap",
        paddingTop: 18, borderTop: "1px dashed rgba(33,30,30,0.2)",
      }}>
        <button
          onClick={onRetry}
          style={{
            padding: "10px 16px",
            background: "transparent",
            border: "1px solid #211E1E", borderRadius: 4,
            fontFamily: "var(--font-mono)",
            fontWeight: 600, fontSize: 12,
            letterSpacing: "0.04em", textTransform: "uppercase",
            color: "#211E1E", cursor: "pointer",
          }}
        >
          ↺ Try a different screenshot
        </button>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          <button
            onClick={onFileTicket}
            className="ss-action-btn"
            style={{
              padding: "11px 18px",
              background: isHardware ? "#211E1E" : "#FFFFFF",
              color: isHardware ? "#FDC831" : "#211E1E",
              border: "1px solid #211E1E", borderRadius: 4,
              boxShadow: isHardware ? "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)" : "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
              fontFamily: "var(--font-mono)",
              fontWeight: 600, fontSize: 12.5,
              letterSpacing: "0.04em", textTransform: "uppercase",
              cursor: "pointer",
            }}
          >
            {isHardware ? "File ticket with the IT Team →" : "File ticket with screenshot"}
          </button>
          {!isHardware && suggestions.length > 0 && (
            <button
              onClick={onOpenGuide}
              className="ss-action-btn"
              style={{
                padding: "11px 18px",
                background: "#211E1E",
                color: "#FDC831",
                border: "1px solid #211E1E", borderRadius: 4,
                boxShadow: "0 1px 2px rgba(33,30,30,.06), 0 8px 24px -14px rgba(33,30,30,.28)",
                fontFamily: "var(--font-mono)",
                fontWeight: 600, fontSize: 12.5,
                letterSpacing: "0.04em", textTransform: "uppercase",
                cursor: "pointer",
                display: "inline-flex", alignItems: "center", gap: 6,
              }}
            >
              Walk me through the fix →
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

